        row_sorted = _row_text_sorted(row, rtl=False)
        # Build row text
        row_text = _norm_space(" ".join([ln.text for ln in row_sorted if _norm_space(ln.text)]))
        if not row_text:
            continue

        # Known plain labels
        if RE_KNOWN_PLAIN_LABEL.fullmatch(row_text):
            fields.append(row_text)
            continue

        # "Other, Please Specify" sometimes appears not-bold; capture if it appears as a left label
        if RE_OTHER_SPECIFY.match(row_text) and min([ln.x0 for ln in row_sorted]) <= 120:
            fields.append(_norm_space(row_text))
            continue

        # Generic "Label:" pattern on left side (avoid instructions)
        # Take only the part before ":" if it looks like a label.
        if ":" in row_text and min([ln.x0 for ln in row_sorted]) <= 120:
            left = _norm_space(row_text.split(":", 1)[0])
            if left and len(left) >= 3 and not RE_NONFIELD_PHRASE.match(left):
                # avoid capturing obvious values/options
                if not _is_probably_option_text(left):
                    fields.append(left)

    # De-dupe
    seen = set()
    out = []
    for f in fields:
        k = f.lower()
        if k in seen:
            continue
        seen.add(k)
        out.append(f)
    return out


# -----------------------------
# Main entry
# -----------------------------
def extract(pages):
    """
    pages: list of page objects; each page has .lines iterable of line objects
           line has: text, x0, y0, size, bold (bool)
    Returns list of dict records: {page, form_name, field_name}
    """
    records = []

    for page_index, page in enumerate(pages, start=1):
        lines = list(getattr(page, "lines", []) or [])
        if not lines:
            continue

        form_name = _detect_form_name(lines) or ""

        # Variable details pages (if present)
        if _is_variable_details_page(lines):
            fields = _extract_fields_variable_details(lines)
        else:
            fields = _extract_fields_crf_page(lines)

            # If CRF extraction yields nothing, try plain-label fallback
            if not fields:
                fields = _extract_plain_labels_fallback(lines)
            else:
                # Even when we have fields, add plain-label "Other, Please Specify" if present and missing
                extra = _extract_plain_labels_fallback(lines)
                if extra:
                    have = {f.lower() for f in fields}
                    for e in extra:
                        if e.lower() not in have:
                            fields.append(e)

        # Final de-dupe per page
        seen = set()
        for field in fields:
            field = _norm_space(field)
            if not field:
                continue
            key = (form_name.lower(), field.lower())
            if key in seen:
                continue
            seen.add(key)
            records.append(
                {
                    "page": page_index,
                    "form_name": form_name,
                    "field_name": field,
                }
            )

    return records
